import os, subprocess, textwrap
os.makedirs("system", exist_ok=True); os.makedirs("constant", exist_ok=True)

XS = [0.0, X0, X0+BLK_L, DUCT_L]      # 0, 80, 120, 200 mm
YS = [0.0, DUCT_W]
ZS = [-BLK_T, 0.0, DUCT_H]            # -10, 0, 30 mm
def V(ix,iy,iz): return iz*8 + iy*4 + ix
verts = [f"({XS[ix]:.6g} {YS[iy]:.6g} {ZS[iz]:.6g})" for iz in range(3) for iy in range(2) for ix in range(4)]

def hexb(ix,iz,n):   # block spanning x[ix..ix+1], full y, z[iz..iz+1]
    a=[V(ix,0,iz),V(ix+1,0,iz),V(ix+1,1,iz),V(ix,1,iz)]
    b=[V(ix,0,iz+1),V(ix+1,0,iz+1),V(ix+1,1,iz+1),V(ix,1,iz+1)]
    return f"    hex ({' '.join(map(str,a+b))}) ({n[0]} {n[1]} {n[2]}) simpleGrading (1 1 1)"
NX=[16,8,16]; NY=10; NZF=10; NZS=4
blocks=[hexb(i,1,(NX[i],NY,NZF)) for i in range(3)] + [hexb(1,0,(NX[1],NY,NZS))]

def fx(ix,iz):  return f"({V(ix,0,iz)} {V(ix,0,iz+1)} {V(ix,1,iz+1)} {V(ix,1,iz)})"      # const-x face
def fy(ix,iy,iz):return f"({V(ix,iy,iz)} {V(ix+1,iy,iz)} {V(ix+1,iy,iz+1)} {V(ix,iy,iz+1)})" # const-y
def fz(ix,iz):  return f"({V(ix,0,iz)} {V(ix+1,0,iz)} {V(ix+1,1,iz)} {V(ix,1,iz)})"      # const-z
inlet=[fx(0,1)]; outlet=[fx(3,1)]
duct=[fz(i,2) for i in range(3)] + [fy(i,j,1) for i in range(3) for j in (0,1)] + [fz(0,1), fz(2,1)]
blkw=[fz(1,0)] + [fy(1,j,0) for j in (0,1)] + [fx(1,0), fx(2,0)]
def patch(name,typ,faces): return f"    {name}
    {{
        type {typ};
        faces
        (
" + "".join(f"            {f}
" for f in faces) + "        );
    }
"

d = "FoamFile
{ version 2.0; format ascii; class dictionary; object blockMeshDict; }

scale 1;

vertices
(
"
d += "".join(f"    {v}
" for v in verts) + ");

blocks
(
" + "
".join(blocks) + "
);

edges ();

boundary
(
"
d += patch("inlet","patch",inlet)+patch("outlet","patch",outlet)+patch("ductWalls","wall",duct)+patch("blockWalls","wall",blkw)+");

mergePatchPairs ();
"
open("system/blockMeshDict","w").write(d)

open("system/controlDict","w").write("FoamFile{version 2.0; format ascii; class dictionary; object controlDict;}
application chtMultiRegionFoam;
startFrom startTime; startTime 0; stopAt endTime; endTime 1; deltaT 1;
writeControl timeStep; writeInterval 1; writeFormat ascii; timeFormat general; runTimeModifiable true;
")
open("system/fvSchemes","w").write("FoamFile{version 2.0; format ascii; class dictionary; object fvSchemes;}
ddtSchemes{default steadyState;} gradSchemes{default Gauss linear;} divSchemes{default none;} laplacianSchemes{default Gauss linear corrected;} interpolationSchemes{default linear;} snGradSchemes{default corrected;}
")
open("system/fvSolution","w").write("FoamFile{version 2.0; format ascii; class dictionary; object fvSolution;}
solvers{}
")
